INSERT INTO lessons (topic_slug,ordinal_no,title,summary,theory,published) VALUES
('conditionals',0,'Câu điều kiện loại 0','Sự thật và quy luật chung','Cấu trúc: If + hiện tại đơn, hiện tại đơn. Dùng cho sự thật hiển nhiên, quy luật và thói quen. Ví dụ: If water reaches 100°C, it boils. Có thể đổi chỗ hai mệnh đề; khi mệnh đề if đứng trước, dùng dấu phẩy.',TRUE),
('conditionals',1,'Câu điều kiện loại 1','Tình huống có thể xảy ra','Cấu trúc: If + hiện tại đơn, will + động từ nguyên mẫu. Dùng cho khả năng thực tế ở hiện tại hoặc tương lai. Ví dụ: If it rains, we will stay home. Không dùng will trong mệnh đề if thông thường.',TRUE),
('conditionals',2,'Câu điều kiện loại 2','Giả định trái thực tế hiện tại','Cấu trúc: If + quá khứ đơn, would + động từ nguyên mẫu. Dùng cho giả định ít khả năng hoặc trái thực tế hiện tại. Ví dụ: If I had more time, I would learn French. Were có thể dùng với mọi chủ ngữ trong cách diễn đạt trang trọng.',TRUE),
('conditionals',3,'Câu điều kiện loại 3','Giả định trái thực tế quá khứ','Cấu trúc: If + had + quá khứ phân từ, would have + quá khứ phân từ. Dùng để nói điều đã không xảy ra trong quá khứ và kết quả tưởng tượng. Ví dụ: If she had left earlier, she would have caught the train.',TRUE);

INSERT INTO questions (lesson_id,prompt,option_a,option_b,option_c,option_d,correct_option,explanation,published) VALUES
(1,'If you heat ice, it ___.','melts','will melt','melted','would melt','A','Loại 0 diễn tả quy luật: hai mệnh đề ở hiện tại đơn.',TRUE),
(1,'Plants die if they ___ enough water.','will not get','do not get','did not get','had not got','B','Điều kiện chung dùng hiện tại đơn: do not get.',TRUE),
(1,'If the sun sets, it ___ dark.','will get','got','gets','would get','C','Sự thật lặp lại dùng gets ở mệnh đề chính.',TRUE),
(1,'When water freezes, it ___ into ice.','turned','will turn','would turn','turns','D','Quá trình tự nhiên được diễn tả bằng hiện tại đơn.',TRUE),
(1,'If I drink coffee late, I ___ badly.','sleep','will sleep','slept','would sleep','A','Thói quen thường xuyên có thể dùng câu điều kiện loại 0.',TRUE),
(1,'Metal expands if you ___ it.','will heat','heat','heated','had heated','B','Mệnh đề if của loại 0 dùng hiện tại đơn.',TRUE),
(1,'If a student misses class, the teacher ___ an email.','sent','would send','sends','will have sent','C','Quy định/thói quen chung dùng hiện tại đơn.',TRUE),
(1,'If you mix red and blue, you ___ purple.','got','will have got','would get','get','D','Kết quả thông thường của việc pha màu dùng hiện tại đơn.',TRUE),
(1,'If babies are hungry, they usually ___.','cry','will cry','cried','would cry','A','Usually chỉ thói quen; dùng cry ở hiện tại đơn.',TRUE),
(1,'If the temperature falls below zero, water ___.','will freeze','freezes','froze','would freeze','B','Quy luật vật lý dùng câu điều kiện loại 0.',TRUE),
(1,'The alarm rings if someone ___ the door.','opened','will open','opens','had opened','C','Điều kiện vận hành thường xuyên dùng opens.',TRUE),
(1,'If you press this switch, the light ___.','will have turned on','turned on','would turn on','turns on','D','Mô tả chức năng cố định của công tắc dùng hiện tại đơn.',TRUE),
(1,'If people eat too much sugar, they often ___ weight.','gain','will gain','gained','would gain','A','Often mô tả xu hướng chung; mệnh đề chính dùng hiện tại đơn.',TRUE),
(1,'Snow melts when the air ___ warm.','will become','becomes','became','would become','B','Mệnh đề thời gian mô tả quy luật dùng becomes.',TRUE),
(1,'If I forget my keys, my neighbor ___ me in.','let','will let','lets','would let','C','Đây là thói quen của người hàng xóm, nên dùng hiện tại đơn.',TRUE),

(2,'If it rains tomorrow, we ___ at home.','stay','stayed','would stay','will stay','D','Loại 1: if + hiện tại đơn, will + động từ nguyên mẫu.',TRUE),
(2,'She will call you if she ___ early.','finishes','will finish','finished','had finished','A','Không dùng will trong mệnh đề if của loại 1.',TRUE),
(2,'If you study tonight, you ___ the test.','pass','will pass','would pass','passed','B','Kết quả tương lai có thể xảy ra dùng will pass.',TRUE),
(2,'If the bus is late, I ___ a taxi.','take','took','will take','would take','C','Loại 1 diễn tả quyết định cho tình huống tương lai.',TRUE),
(2,'We will go hiking if the weather ___ clear.','will be','was','had been','is','D','Mệnh đề if dùng hiện tại đơn is dù nói về tương lai.',TRUE),
(2,'If he does not hurry, he ___ the train.','will miss','misses','missed','would miss','A','Kết quả có thể xảy ra trong tương lai: will miss.',TRUE),
(2,'If I have time this weekend, I ___ you.','visited','will visit','would visit','visit','B','Điều kiện thực tế tương lai dùng will visit.',TRUE),
(2,'They will be pleased if you ___ them.','will invite','invited','invite','had invited','C','Sau if trong loại 1 dùng hiện tại đơn invite.',TRUE),
(2,'If the shop closes early, we ___ online.','shop','shopped','would shop','will shop','D','Kết quả dự kiến dùng will + động từ nguyên mẫu.',TRUE),
(2,'If you do not wear a coat, you ___ cold.','will feel','feel','felt','would feel','A','Đây là dự đoán thực tế, dùng will feel.',TRUE),
(2,'I will lend you the book if you ___ it back.','will bring','bring','brought','had brought','B','Mệnh đề điều kiện dùng hiện tại đơn bring.',TRUE),
(2,'If Maria arrives first, she ___ seats for us.','saved','saves','will save','would save','C','Dự đoán hành động sắp tới dùng will save.',TRUE),
(2,'You will understand the rule if you ___ the example.','will read','readed','had read','read','D','Read ở đây là hiện tại đơn sau if.',TRUE),
(2,'If the flight is cancelled, we ___ the airline.','will contact','contact','contacted','would contact','A','Kết quả tương lai của một điều kiện có thật dùng will contact.',TRUE),
(2,'He will improve if he ___ every day.','will practise','practises','practised','had practised','B','Mệnh đề if cần hiện tại đơn: practises.',TRUE),

(3,'If I had more free time, I ___ a novel.','write','will write','would write','had written','C','Loại 2: if + quá khứ đơn, would + động từ nguyên mẫu.',TRUE),
(3,'If she were here, she ___ what to do.','knows','will know','knew','would know','D','Giả định hiện tại trái thực tế dùng would know.',TRUE),
(3,'If I won the lottery, I ___ around the world.','would travel','will travel','travel','had travelled','A','Tình huống giả định ít khả năng dùng would travel.',TRUE),
(3,'He would play more often if he ___ a guitar.','has','had','will have','had had','B','Mệnh đề if loại 2 dùng quá khứ đơn had.',TRUE),
(3,'If we lived near the sea, we ___ swimming every day.','go','will go','would go','went','C','Kết quả tưởng tượng ở hiện tại dùng would go.',TRUE),
(3,'I would help you if I ___ the answer.','know','will know','had known','knew','D','Giả định trái thực tế hiện tại: if I knew.',TRUE),
(3,'If it were warmer, we ___ outside.','would eat','will eat','ate','had eaten','A','Cấu trúc loại 2 dùng would + eat.',TRUE),
(3,'If you spoke slower, I ___ you better.','will understand','would understand','understood','had understood','B','Kết quả của giả định hiện tại dùng would understand.',TRUE),
(3,'If my apartment were bigger, I ___ a dog.','have','will have','would have','had had','C','Would have là kết quả giả định; không phải hiện tại hoàn thành.',TRUE),
(3,'She would join us if she ___ in town.','is','will be','had been','were','D','Giả định hiện tại với be thường dùng were.',TRUE),
(3,'If I were you, I ___ the offer.','would accept','will accept','accepted','had accepted','A','If I were you là cấu trúc lời khuyên loại 2.',TRUE),
(3,'If the library stayed open later, students ___ there.','will study','would study','studied','had studied','B','Kết quả giả định dùng would study.',TRUE),
(3,'I would buy that camera if it ___ less.','costs','will cost','cost','had cost','C','Cost có dạng quá khứ giống hiện tại; đi với if loại 2.',TRUE),
(3,'If we knew her address, we ___ a card.','send','will send','sent','would send','D','Không biết địa chỉ ở hiện tại nên dùng would send.',TRUE),
(3,'If the train were faster, more people ___ it.','would use','will use','used','had used','A','Hệ quả giả định hiện tại dùng would use.',TRUE),

(4,'If she had studied, she ___ the exam.','passes','will pass','would have passed','would pass','C','Loại 3: if + had + V3, would have + V3.',TRUE),
(4,'If we had left earlier, we ___ the bus.','catch','will catch','would catch','would have caught','D','Kết quả tưởng tượng trong quá khứ dùng would have caught.',TRUE),
(4,'If I had known, I ___ you.','would have told','will tell','told','would tell','A','Điều đã không xảy ra trong quá khứ dùng would have told.',TRUE),
(4,'He would have arrived on time if he ___ a taxi.','takes','had taken','would take','has taken','B','Mệnh đề if loại 3 dùng had taken.',TRUE),
(4,'If they had checked the map, they ___ lost.','do not get','will not get','would not have got','would not get','C','Kết quả quá khứ không có thật dùng would not have got.',TRUE),
(4,'If it had not rained, we ___ the match.','play','will play','would play','would have played','D','Trận đã bị lỡ trong quá khứ; dùng would have played.',TRUE),
(4,'If you had called me, I ___ at the station.','would have met you','will meet you','met you','would meet you','A','Mệnh đề kết quả loại 3 dùng would have + quá khứ phân từ.',TRUE),
(4,'She would have been happier if she ___ the job.','accepts','had accepted','would accept','has accepted','B','Điều kiện trong quá khứ dùng had accepted.',TRUE),
(4,'If the team had trained harder, they ___ the final.','win','will win','might have won','would win','C','Might have won diễn tả khả năng kết quả quá khứ trong loại 3.',TRUE),
(4,'We would not have missed the show if the car ___ down.','does not break','will not break','would not break','had not broken','D','If + had not + V3 diễn tả điều kiện trái thực tế quá khứ.',TRUE),
(4,'If I had saved the file, I ___ my work.','would not have lost','will not lose','did not lose','would not lose','A','Kết quả quá khứ giả định dùng would not have lost.',TRUE),
(4,'If the chef had added salt, the soup ___ better.','tastes','would have tasted','will taste','would taste','B','Would have tasted là kết quả tưởng tượng trong quá khứ.',TRUE),
(4,'She might have seen the message if she ___ her phone.','checks','would check','had checked','has checked','C','Sau if của loại 3 dùng had checked.',TRUE),
(4,'If we had booked ahead, we ___ a table.','get','will get','would get','would have got','D','Việc đặt bàn đã không xảy ra; kết quả dùng would have got.',TRUE),
(4,'If the lights had worked, I ___ the sign.','would have seen','will see','saw','would see','A','Kết quả trái thực tế trong quá khứ dùng would have seen.',TRUE);
